    midnight_blue:        { value: "#0000AA", label: "Midnight Blue" }
    navy:                 { value: "#000055", label: "Navy" }
    black:                { value: "#000000", label: "Black" }

theme:
  schemes:
    dark:
      label: "Dark"
      colors: { bg: color.black, fg: color.white, dim: color.silver_chalice }
    navy:
      label: "Navy"
      colors: { bg: color.navy, fg: color.shalimar, dim: color.cornflower_blue }

config:
  style:
    default: dark
    choices:
      dark: { scheme: dark }
      navy: { scheme: navy }
  accent_color:
    default: color.web_orange
    choices: any # every palette swatch, by its label
  data_color:
    default: color.baby_blue
    choices: [color.baby_blue, color.white, color.laser_lemon, color.screamin_green]

static:
  background:
    type: rectangle
    at: { anchor: center }
    size: { width: 100%, height: 100% }
    color: color.bg

  accent_ring:
    type: arc
    at: { anchor: center }
    radius: 94%r
    thickness: 4px
    start_angle: 0deg
    sweep: 360deg
    color: color.accent

elements:
  date:
    type: text
    text: "{date.today:%a %d}"
    font: FONT_TINY
    at: { anchor: center, dy: -40%r }
    color: color.dim

  clock:
    type: text
    text: "{time.clock:%h:%M}"
    font: FONT_NUMBER_HOT
    at: { anchor: center, dy: 6%r }
    color: color.fg

  steps:
    type: text
    text: "{activity.steps:d}"
    font: FONT_SMALL
    at: { anchor: center, dy: 52%r }
    color: color.data
    absent: "--"
